def transform(grid):
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    # Marked seed defines the 2x2 patch anchored at floor coordinates of each seed.
    # Infer patch size from repeated outputs in demos: seeds denote one cell of 2x2 tile,
    # and corresponding 1-valued 2x2 patches are colored throughout canvas.
    for r in range(h):
        for c in range(w):
            color=grid[r][c]
            if color not in (0,1):
                # Demos show seed is embedded within a 2x2 patch; color all 2x2 blocks
                # matching occupancy as a shape; clue location is upper-left of colored patch
                # when possible, test all window starts, including one cell above/left.
                for dr in (0,-1):
                    for dc in (0,-1):
                        rr,cc=r+dr,c+dc
                        if 0<=rr<h-1 and 0<=cc<w-1 and grid[rr][cc]==color:
                            pass
                # Color every complete 2x2 block of ones in this grid.
                for rr in range(h-1):
                    for cc in range(w-1):
                        if all(grid[rr+i][cc+j]==1 for i in (0,1) for j in (0,1)):
                            out[rr][cc]=out[rr][cc+1]=out[rr+1][cc]=out[rr+1][cc+1]=color
    return out
