def transform(grid):
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    seen=set()
    for r in range(h):
      for c in range(w):
        if grid[r][c] in (0,) or (r,c) in seen: continue
        # 4-connected nonzero component
        stack=[(r,c)]; seen.add((r,c)); comp=[]; colors=[]
        while stack:
          y,x=stack.pop(); comp.append((y,x))
          if grid[y][x] not in (0,1): colors.append(grid[y][x])
          for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
            if 0<=yy<h and 0<=xx<w and grid[yy][xx]!=0 and (yy,xx) not in seen:
              seen.add((yy,xx)); stack.append((yy,xx))
        if not colors: continue
        color=colors[0]; cells=set(comp)
        for y,x in comp:
          if grid[y][x] != 1: continue
          if all((yy,xx) in cells for yy in range(y-1,y+2) for xx in range(x-1,x+2)):
            out[y][x]=color
    return out
